const D = { density:.55, energy:.6, hue:190, speed:1, scale:1, warp:.35, x:.5, y:.42, seed:0, style:'neon', pattern:'chase', act:'sweep' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return q - Math.floor(q); };
const cl = (v,a,b) => v<a?a:v>b?b:v;
const TAU = 6.28318530718;
const sty = P.style, H = P.hue;
const hz = cl(P.y, .25, .7) * height;
const cx = cl(P.x, .1, .9) * width;
const groundH = Math.max(24, height - hz);
const yOf = t => hz + Math.pow(cl(t,0,1), 1.8) * groundH;
const hwOf = t => width * (.028 + t*1.05) * .5 * P.scale * (1 + P.warp*.5);
const NR = Math.round(7 + P.density*9);
const NC = Math.round(5 + P.density*8);
const FFT = (A.fft && A.fft.length) ? A.fft : null;

S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
S.tre  = (S.tre||0)*.8 + (A.treble||0)*.2;
const glow = (.4 + .6*P.energy) * (.5 + .6*K.intensity);
const kick = Math.min(1, K.pulse*(.5 + .5*K.intensity) + S.bass*.6);

// real-time chase phase (integrates seconds — never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.55 + .9*K.intensity);
if (P.act === 'pulse') sp *= .45 + 1.3*kick;
if (P.act === 'build') sp *= .3 + 1.5*(.5 + .5*Math.sin(K.t*.05 + K.section*.8));
S.chase = (S.chase||0) + dt*sp*.5;
const chase = S.chase;

// cached dark floor backdrop (keyed on size/style/hue/geometry)
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.y*20)+'|'+Math.round(P.scale*8)+'|'+Math.round(P.warp*10);
if (!S.base || S.key !== key) {
  const g = (S.base && S.base.width===width && S.base.height===height) ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 46;
  for (let i=0;i<STR;i++){ const f=i/STR, y=hz + f*groundH;
    let h,s,b;
    if (sty==='blueprint'){ h=H; s=68; b=14 + 10*f; }
    else if (sty==='sodium'){ h=32; s=42-24*f; b=6 + 9*f; }
    else if (sty==='halftone'){ h=H; s=8; b=7 + 8*f; }
    else { h=H; s=55-20*f; b=3 + 7*f; }   // neon: near-black with faint hue
    g.fill(h, cl(s,4,90), b, 100); g.rect(0, y, width, groundH/STR + 1);
  }
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// cell brightness field
const bright = (r,c) => {
  const tc = (r+.5)/NR;
  const fv = FFT ? (FFT[Math.floor((r/NR)*FFT.length)]||0) : 0;
  let br;
  if (P.pattern==='ripple'){ const dd = Math.hypot((c-(NC-1)/2)*.9, (NR-r)*.7); br = .5 + .5*Math.sin(dd*.8 - chase*TAU); }
  else if (P.pattern==='columns'){ br = .5 + .5*Math.sin(c*.95 - chase*TAU*1.2); }
  else if (P.pattern==='fft'){ br = .12 + .88*fv; }
  else if (P.pattern==='random'){ const step = Math.floor(chase*3); br = .15 + .85*fr(r*NC + c + step*57.3); }
  else { br = .5 + .5*Math.sin(r*.62 + c*.34 - chase*TAU); }  // chase (default)
  br = cl(br + kick*.28*Math.sin(r*.5 + c*1.3) + S.tre*.35*fv, 0, 1);
  return br;
};

// filled perspective cells
noStroke();
for (let r=0;r<NR;r++){
  const t0=r/NR, t1=(r+1)/NR;
  const y0=yOf(t0), y1=yOf(t1), hw0=hwOf(t0), hw1=hwOf(t1);
  const near=(r+.5)/NR;
  for (let c=0;c<NC;c++){
    const u0=c/NC, u1=(c+1)/NC, br=bright(r,c);
    const xa=cx-hw0+u0*2*hw0, xb=cx-hw0+u1*2*hw0;
    const xc=cx-hw1+u1*2*hw1, xd=cx-hw1+u0*2*hw1;
    if (sty==='halftone'){
      const mx=(xa+xb+xc+xd)/4, my=(y0+y1)/2;
      const cw=Math.min(Math.abs(xb-xa), Math.abs(y1-y0));
      const rad=cw*(.15+.72*br);
      fill(H, 6, 4 + 92*br, 100); ellipse(mx, my, rad, rad*.7);
      continue;
    }
    let h,s,b;
    if (sty==='blueprint'){ h=(H + (P.pattern==='fft'?r*3:0))%360; s=60; b=16 + 34*br; }
    else if (sty==='sodium'){ h=34 - 6*br; s=95 - 55*br; b=8 + 90*br; }
    else { h=(H + (P.pattern==='fft'? r*4 : 0) + (br>.7? -12:0))%360; s=95 - 45*br; b=6 + 92*br; } // neon
    fill(h, cl(s,0,100), cl(b,2,100), 100);
    quad(xa,y0, xb,y0, xc,y1, xd,y1);
  }
}

// additive bloom on the brightest cells only
push(); blendMode(ADD); noStroke();
for (let r=0;r<NR;r++){
  const t0=r/NR, t1=(r+1)/NR;
  const y0=yOf(t0), y1=yOf(t1), hw0=hwOf(t0), hw1=hwOf(t1);
  for (let c=0;c<NC;c++){
    const br=bright(r,c); if (br < .62) continue;
    const u0=c/NC, u1=(c+1)/NC;
    const xa=cx-hw0+u0*2*hw0, xb=cx-hw0+u1*2*hw0;
    const xc=cx-hw1+u1*2*hw1, xd=cx-hw1+u0*2*hw1;
    const h = sty==='sodium'?36 : sty==='blueprint'?(H+10)%360 : sty==='halftone'?H : (H+6)%360;
    fill(h, sty==='sodium'?70:(sty==='halftone'?10:80), 100, cl((br-.62)*70*glow, 0, 32));
    quad(xa,y0, xb,y0, xc,y1, xd,y1);
  }
}
pop();

// glowing perspective grid lines on top (structure)
noFill();
const gh = sty==='sodium'?38 : sty==='halftone'?H : (H+ (sty==='blueprint'?30:20))%360;
for (let r=0;r<=NR;r++){
  const t=r/NR, y=yOf(t), hw=hwOf(t), near=t;
  stroke(gh, sty==='halftone'?10:70, 100, (10 + 42*near)*(.5 + .6*glow));
  strokeWeight(.5 + near*1.4);
  line(cx-hw, y, cx+hw, y);
}
for (let c=0;c<=NC;c++){
  const u=c/NC, d=u-.5;
  const xT=cx + d*2*hwOf(0), xB=cx + d*2*hwOf(1);
  stroke(gh, sty==='halftone'?10:70, 100, (14 + 30)*(.5 + .55*glow));
  strokeWeight(.7);
  line(xT, hz, xB, height);
}

// horizon glow bar (partial, safe)
push(); blendMode(ADD); noStroke();
const flare = (kick*.6 + K.swell*.3)*glow;
for (let i=0;i<4;i++){ const rr=(4-i)*groundH*.05*(1+flare);
  fill(gh, sty==='sodium'?60:55, 96, 3 + 8*flare); rect(0, hz-rr*.35, width, rr*.7); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
